# Try the fold transformation with mirroring
def fold_at_column(grid, fold_col):
    """Fold grid at fold_col, mirroring cols > fold_col into cols < fold_col"""
    new_width = fold_col + 1
    result = [[0]*new_width for _ in range(len(grid))]

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if c <= fold_col:
                result[r][c] = grid[r][c]
            else:
                # Mirror: col 8 -> 6, col 9 -> 5, etc.
                mirrored_c = fold_col - (c - fold_col)
                result[r][mirrored_c] = grid[r][c]

    return result

