# Left of divider has two bands: cols 0-2 (band A) and cols 4-6 (band B)
# Items in band A come after band B if sorted by column descending
# But within same band, higher row value comes first

def get_color_band(grid, divider_col):
    """Assign colors to bands based on their column range"""
    # Get all positions for each color
    color_ranges = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            if color not in [0, 4]:  # Exclude empty and divider
                if color not in color_ranges:
                    color_ranges[color] = {'min_c': float('inf'), 'max_c': 0, 'min_r': float('inf')}
                color_ranges[color]['min_c'] = min(color_ranges[color]['min_c'], c)
                color_ranges[color]['max_c'] = max(color_ranges[color]['max_c'], c)
                color_ranges[color]['min_r'] = min(color_ranges[color]['min_r'], r)

    # Assign band: right of divider gets band 0 (highest priority)
    # Then group by columns relative to divider
    def get_band(color):
        avg_c = sum((color_ranges[color]['min_c'] + color_ranges[color]['max_c']) // 2) / 2
        if avg_c > divider_col:
            return ('RIGHT', 0)
        elif avg_c < divider_col:
            # Check which side of divider (left or center)
            return ('LEFT_LEFT' if avg_c < divider_col else ('LEFT_RIGHT' if avg_c <= divider_col + 2 else 'LEFT_MID'))

    # Actually let me simplify
    # For demo: cols 0-6 are left of divider at col 7
    # Right split: cols 0-2 vs cols 4-6

    result = {}
    for color, info in color_ranges.items():
        avg_c = (info['min_c'] + info['max_c']) / 2
        if avg_c > divider_col:
            band = 'R'
            sub = 0
        else:
            # Determine which left region
            if info['max_c'] >= divider_col - 2:  # Close to divider
                band = 'L_mid'
                sub = 1  # Higher column number = higher priority (comes first in output?)
            else:
                band = 'L_far'
                sub = 2

        result[color] = (band, sub, info['min_r'])

    # Sort by band priority, then by row (descending means higher row index = higher priority)
    sorted_colors = sorted(result.keys(), 
                          key=lambda x: (result[x][0], result[x][1], -result[x][2]))

    print("Sorted colors:", sorted_colors)
    return sorted_colors

